 out=Path(out);started=time.perf_counter();before=memory();analysis=out if not (out/'M3_4B_PRODUCTION_READINESS_REPORT.md').exists() else out/('report_refresh_'+str(time.time_ns()));analysis.mkdir(exist_ok=True);m=read(out/'execution_manifest.json');a=read(out/'diversity_audit.json');stress=read(out/'monitor_stress.json');recovery=read(out/'recovery_validation.json');tests=read(out/'test_results.json')
 aggregate=reduce_summaries((out/'attempts/monitor').glob('*.json'));profiles=[];generation=[];validation=[];states=updates=0;matched=[];quality=Counter();maxima={};rows=[]
