  rows.append(dict(index=i,mesh=j['configuration']['mesh'],support=j['configuration']['support'],direction=j['configuration']['direction'],aspect=j['configuration']['aspect'],partition=j['partition'],states=g['states'],updates=g['updates'],stop=q['stop'],pg=q['projected_gradient_inf'],reference_candidate=q['reference_screen_candidate'],volume_feasible=q['volume_feasible'],peak_worker=gen['monitor']['worker_peak_rss_mib'],parent_after=val['monitor']['parent_after_mib']))
